package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.junit.jupiter.api.Test;

class PackedPlanDeferredDiagnosticTest {
	@Test
	void ordinaryPackedMaterializationDefersTraversalUntilReadOrActualCacheCopy() {
		TupleExpr source = new StatementPattern(Var.of("subject"), Var.of("predicate"), Var.of("object"));
		TupleExpr ordinary = PackedCascadesPlanner.optimize(source, OptimizationGoal.root()).selectedPlan();
		assertTrue(ordinary.canDetachPlanningState((key, value) -> true));
		assertFalse(ordinary.accountDetachedPlanningState((object, bytes) -> true,
				(key, value, account) -> true),
				"ordinary materialization must still own the O(1) deferred producer, not eagerly frozen tokens");
		SingletonSet detachedMetrics = new SingletonSet();
		// Only diagnostic state is tested here; execution metadata is deliberately not copied into this dummy node.
		assertTrue(ordinary.copyDetachedPlanningStateTo(detachedMetrics, (key, value, target) -> true));
		assertTrue(detachedMetrics.accountDetachedPlanningState((object, bytes) -> true,
				(key, value, account) -> true), "only the actual cache copy freezes final owned diagnostic data");
		String json = detachedMetrics.getStringMetricPlanned("optimizer.packedExplanationJson");
		assertTrue(json.contains("\"schema\":2"), json);
		assertSame(json, detachedMetrics.getStringMetricPlanned("optimizer.cascadesTraceJson"));
		assertEquals(ordinary.getStringMetricPlanned("optimizer.packedExplanationJson"), json);
		assertEquals(ordinary.getStringMetricPlanned("optimizer.packedExplanation"),
				detachedMetrics.getStringMetricPlanned("optimizer.packedExplanation"));
	}
}
